          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address</label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            placeholder="jordan@example.com"
            aria-describedby="email-error"
            required
          >
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number <span class="optional">(optional)</span></label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            placeholder="(555) 123-4567"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Use a US phone number format, such as (555) 123-4567 or 555-123-4567.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Contact support</button>
      </form>

      <p class="success-message" id="success-message" role="status">Thanks. Your support request is ready to send.</p>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const successMessage = document.querySelector("#success-message");

    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Enter your full name.";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmedValue) {
            return "Enter your email address.";
          }

          return emailPattern.test(trimmedValue) ? "" : "Enter a valid email address, such as name@example.com.";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const phonePattern = /^(\+1[\s.-]?)?(\([2-9]\d{2}\)|[2-9]\d{2})[\s.-]?[2-9]\d{2}[\s.-]?\d{4}$/;

          if (!trimmedValue) {
            return "";
          }

          return phonePattern.test(trimmedValue) ? "" : "Enter a phone number in the expected format, such as (555) 123-4567.";
        }
      }
    };

    function setFieldState(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
